(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ro"] = {"ui":{"skip":"Sari la conținut","back":"← Înapoi la AI-gile","lang.button":"Limba: {name}","lang.dialog":"Alege o limbă","lang.search":"Caută limbi","lang.none":"Nicio limbă nu se potrivește","lang.notYet":"{name} nu e tradusă încă","theme.aria":"Comută între tema luminoasă și cea întunecată","theme.toLight":"Treci la tema luminoasă","theme.toDark":"Treci la tema întunecată","words.underline":"Subliniază aceste cuvinte în pagină","words.underlineHelp":"Treci cu mouse-ul peste un cuvânt punctat sau atinge-l ca să vezi ce înseamnă.","index.title":"AI-gile: echipa ta de dezvoltare AI, pe o singură tablă","index.description":"AI-gile este o tablă kanban pentru echipe de programare cu AI. Ele lucrează cât dormi; tu primești o grămadă mică de lucruri de decis, de testat și de acceptat.","hero.logoAlt":"Pictograma tablei AI-gile","hero.h1.html":"Echipa ta de dezvoltare AI, pe o singură&nbsp;tablă.","hero.alpha":"🐣 Pre-alfa închis","hero.alphaTitle":"Început și neterminat: mulțumim că îl încerci!","hero.lede":"Ele construiesc cât dormi. Tu te trezești cu o grămadă mică: câteva întrebări, câteva lucruri de testat, un diamant mov sau două. Un clic, accepți, și te întorci la cafea.","dl.windows":"Aplicație pentru Windows","dl.browser":"Rulează-l în browser","dl.soon":"În curând","dl.notify":"🔔 Anunță-mă când se deschide","dl.notifySmall":"Alfa sau beta","hero.secondary":"Agile, dar echipa nu are nevoie de cafeaua de la stand-up. (Fac stand-up oricum.)","pitch.h2":"AI-gile în câte cuvinte vrei","pitch.lede":"Alege o lungime, de la un cuvânt la 144. Fiecare lungime e o descriere aparte, scrisă pentru mărimea ei. Trage de cursor sau folosește săgețile.","pitch.rangeLabel":"Lungimea în cuvinte","pitch.dice":"🎲 altă versiune","pitch.words.one":"{n} cuvânt","pitch.words.other":"{n} de cuvinte","pitch.letters.one":"{n} literă","pitch.letters.other":"{n} de litere","pitch.chars.one":"{n} caracter","pitch.chars.other":"{n} de caractere","count.line.html.one":"{n} card pe tablă chiar acum","count.line.html.other":"{n} de carduri pe tablă chiar acum","features.aria":"Ce face","f.pile.h":"O singură grămadă pentru tine","f.pile.html":"<b>Pentru tine</b> adună tot ce te așteaptă, din toate proiectele: întrebări, lucruri de testat, sarcini pe care le poate face doar un om. Coada ta spune ce urmează și cât durează.","f.sleep.h":"Echipe care lucrează cât dormi","f.sleep.p":"Fiecare proiect are un lider și o echipă de agenți AI. Lași un comentariu la un card, echipa se trezește, face treaba și ți-l dă înapoi cu pași pe care îi poate urma și un om obosit.","f.tester.h":"Un tester AI verifică primul","f.tester.p":"Înainte să ajungă la tine, un tester urmează pașii într-o copie a aplicației și arată ce a văzut, cu o captură de ecran. Răsfoiești rapid ce a trecut și accepți dintr-un clic.","f.proof.h":"Dovezi, nu promisiuni","f.proof.p":"Fiecare predare arată ce s-a schimbat: fișierele, diferențele, capturile de ecran. Nu mai deschizi fiecare aplicație ca să afli dacă e gata.","f.chat.h":"Vorbește cu liderii tăi","f.chat.p":"O bară în stil Discord: o pictogramă pentru fiecare proiect, diamante mov pentru ce are nevoie de tine. Trimite unui lider o idee; o transformă în carduri și într-un plan, cu un buton ✅ Go.","f.tidy.h":"Se ține singură în ordine","f.tidy.p":"Cardurile înrudite se unesc într-unul, titlurile încurcate se repară, iar o verificare a tokenilor ține codul suplu. Mai puține lucruri între care să sari, mai puține de gândit.","f.private.h":"A ta, pe calculatorul tău","f.private.li1":"Tabla rulează pe calculatorul tău și răspunde numai ție.","f.private.li2":"Mesajele private dintre oameni sunt criptate de la un capăt la altul.","f.private.li3":"Fără conturi, fără urmăritoare, fără cookie-uri.","f.lang.h":"În limba ta","f.lang.p":"Peste 120 de limbi, de la neerlandeză, galeză și japoneză până la limba piraților, a lui Yoda și klingoniană, cu o trecere rapidă înapoi la engleză pentru cuvintele de dezvoltatori.","tl.aria":"Cronologie de la prima discuție până la foaia de parcurs","tl.h2":"De la prima discuție la ce urmează","tl.lede":"Date și ore reale, în fusul tău orar. După azi e planul, fără date promise.","tl.today":"Azi","tl.planned":"planificat","tl.cards.one":"{n} card","tl.cards.other":"{n} de carduri","join.h2":"Vino și tu","join.lede":"AI-gile e construit de un om mic și de o mulțime de agenți răbdători. Deocamdată e privat, într-un alfa închis, cu prieteni. Vrei să-l încerci când se deschide?","join.btn":"Spune-mi că ești interesat","join.small":"Îți scriem pe e-mail, nimic altceva","footer.tag":"AI-gile. Fără urmăritoare, fără cookie-uri, fără cafea de stand-up.","footer.licence":"Licență pentru firme","footer.status":"Stare","footer.privacy":"Ce păstrăm","form.sending":"Se trimite…","form.failed":"N-a mers: mai încearcă mai târziu.","form.offline":"Nu am ajuns la AI-gile: mai încearcă mai târziu.","form.keep":"Folosim asta doar ca să-ți răspundem, apoi o ștergem. Fără urmăritoare, fără cookie-uri.","form.keepLink":"Ce păstrăm","interest.title":"AI-gile: anunță-mă când se deschide alfa","interest.description":"Lasă-ți e-mailul ca să afli când se deschide alfa sau beta închisă a AI-gile.","interest.h1":"🔔 Anunță-mă când se deschide","interest.lede":"AI-gile e în pre-alfa închis. Lasă-ți e-mailul și îți scriem o singură dată, când e loc și pentru tine.","interest.email":"E-mailul tău","interest.which":"Ce test?","interest.alpha":"Alfa închis: timpuriu, aspru, cu multe schimbări","interest.beta":"Beta: mai stabil, mai târziu","interest.both":"Oricare, care vine mai întâi","interest.submit":"Pune-mă pe listă","interest.thanks":"Mulțumim! Ești pe listă.","licence.title":"AI-gile: licență pentru firme","licence.description":"Folosești AI-gile în firma ta? Cere o licență gratuită pentru firme.","licence.h1":"📜 Licență pentru firme","licence.lede":"Folosești AI-gile la serviciu? Spune-ne cine ești și ce faci. Dacă face puțin bine, licența e gratuită.","licence.company":"Firma","licence.website":"Site web","licence.what":"Ce faci","licence.how":"Cum ajută lumea","licence.email":"E-mail","licence.submit":"Trimite cererea","licence.thanks":"Mulțumim! Îți răspundem pe e-mail.","status.title":"Starea AI-gile","status.h1":"Starea AI-gile","status.quiet":"Totul e liniștit","status.intro":"Funcționează AI-gile chiar acum? Pagina asta verifică site-ul, partajarea tablelor, apelurile și descărcarea la fiecare 5 minute.","status.up":"Funcționează (a răspuns în {ms} ms)","status.slow":"N-a răspuns la ultima verificare, reîncerc","status.down":"Nu funcționează: n-a răspuns la ultimele două verificări","status.svc.web":"Site","status.svc.web.offers":"Site-ul ăsta: ce e AI-gile și formularul de interes","status.svc.boards":"Partajarea tablelor","status.svc.boards.offers":"Table publice, mesaje între prieteni și invitații","status.svc.calls":"Apeluri","status.svc.calls.offers":"Voce, video și partajarea ecranului în AI-gile","status.svc.download":"Descărcare","status.svc.download.offers":"Programul de instalare pentru Windows și linkurile de invitație","status.checking":"Se verifică…","status.offline":"Nu pot contacta serviciul de stare acum (reîncerc)","status.updated":"actualizat {ago}","status.justNow":"chiar acum","status.min":"acum {n} min","status.hours":"acum {n} h","status.days":"acum {n} z","privacy.title":"AI-gile: ce păstrăm","privacy.h1":"Ce păstrăm","privacy.lede":"Pe scurt: doar ce ne trimiți tu, și nu pentru mult timp.","privacy.only":"Doar ce ne trimiți: ce scrii într-un formular, cum ar fi e-mailul tău. Nimic altceva despre tine.","privacy.sealed":"E sigilat, ca serverul nostru să nu-l poată citi: în browserul tău, înainte să plece (într-un browser mai vechi, în clipa în care ajunge). Doar tabla noastră îl poate deschide.","privacy.server":"E șters de pe server imediat ce ajunge pe tabla noastră. Orice a rămas acolo după 30 de zile e șters oricum.","privacy.board":"Îl păstrăm pe tabla noastră doar până îți răspundem, apoi îl ștergem și de acolo.","privacy.none":"Fără urmăritoare, fără cookie-uri, fără statistici.","privacy.local":"Limba ta și alegerea temei luminoase sau întunecate rămân în browserul tău. Nu ne sunt trimise niciodată.","privacy.ask":"Vrei să dispară mai devreme? Răspunde la e-mailul nostru și spune-ne.","live.h2":"Privește-l cum se construiește, în direct","live.caption":"Fiecare card este ascuns: vezi forma muncii, nu cuvintele.","live.watching.one":"în direct: {n} privește","live.watching.other":"în direct: {n} privesc","live.last.now":"Ultimul card a fost mutat chiar acum","live.last.min.one":"Ultimul card a fost mutat acum {n} min","live.last.min.other":"Ultimul card a fost mutat acum {n} min","live.last.hour.one":"Ultimul card a fost mutat acum {n} oră","live.last.hour.other":"Ultimul card a fost mutat acum {n} ore","live.last.day.one":"Ultimul card a fost mutat acum {n} zi","live.last.day.other":"Ultimul card a fost mutat acum {n} zile","live.offline":"Tabloul live ia o mică pauză. Revino în curând.","live.cols":"Backlog|De făcut|În lucru|Echipa verifică|Așteaptă testul tău|Pentru echipă|Gata","pitch.words.few":"{n} cuvinte","pitch.letters.few":"{n} litere","pitch.chars.few":"{n} caractere","count.line.html.few":"{n} carduri pe tablă chiar acum","tl.cards.few":"{n} carduri"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboți.","Delegat."]},{"n":2,"texts":["Kanban robotic.","Agenți, organizați.","Idei, construite."]},{"n":3,"texts":["Kanban pentru roboți.","Ideile devin funcții.","Kanban gratuit pentru agenți."]},{"n":5,"texts":["O tablă kanban condusă de agenți.","Tu scrii carduri. Agenții construiesc.","Gratuit, local, testat, puțin caraghios."]},{"n":8,"texts":["O tablă kanban gratuită unde lucrează agenți AI.","Scrii o idee. Agenții o construiesc. Tu accepți.","Agile pentru un om și mulți roboți răbdători."]},{"n":13,"texts":["O tablă kanban pe calculatorul tău, unde agenți AI preiau cardurile.","Scrii o idee. O echipă de agenți o construiește. Un tester o verifică.","Gratuit, fără conturi, fără urmăritoare: o tablă, niște roboți și tu la comandă."]},{"n":21,"texts":["AI-gile este o tablă kanban pentru lucrul cu agenți AI de programare. Ei preiau cardurile; tu le testezi și le accepți.","Fiecare proiect primește un lider și o echipă de agenți AI. Lași un comentariu la orice card și echipa se pune pe treabă.","O listă personală de sarcini, gratuită, care rulează pe calculatorul tău. Muncitorii sunt roboți. Cel care spune da ești tu."]},{"n":34,"texts":["Pui ideile pe o tablă. O echipă de agenți AI le face funcții care merg, le testează și ți le dă înapoi cu pași de încercat. Nimic nu e gata până nu spui tu că e gata.","AI-gile este o tablă kanban făcută în casă, pe care Rich a construit-o cu mult ajutor de la agenții pe care acum îi coordonează. E gratuită, rulează pe calculatorul tău și se dă prietenilor, nu se vinde.","Imaginează-ți o tablă kanban obișnuită, cu coloane de la Backlog până la Gata, doar că cardurile sunt preluate de agenți AI. Ei raportează cum merge, întreabă când se blochează și așteaptă mereu încuviințarea ta."]},{"n":55,"texts":["AI-gile este o tablă kanban în care echipa e făcută din agenți AI. Fiecare proiect are un lider care planifică munca și ajutoare care o construiesc. Când o funcție e gata, un tester AI o încearcă și face o captură de ecran, apoi ajunge în grămada ta. O accepți sau lași un comentariu și o refac.","A început ca felul în care un singur om ținea evidența multor sesiuni de programare cu AI deodată și a crescut într-o tablă adevărată. Rulează pe calculatorul tău, nu cere cont și n-are urmăritoare. E gratuită pentru prieteni și pentru oricine e curios. E și neterminată, așa că așteaptă-te la colțuri aspre și la câte o surpriză.","Iată varianta cinstită. Ideile tot tu trebuie să le ai, iar rezultatele tot tu trebuie să le verifici. Ce face AI-gile este tot ce e între ele: ține cardurile în ordine, trezește agentul potrivit când comentezi, arată exact ce s-a schimbat și strânge totul într-o singură grămadă scurtă pentru tine."]},{"n":89,"texts":["AI-gile este o tablă kanban gratuită pe care o rulezi pe propriul calculator. În loc de oameni, fiecare proiect are o echipă de agenți AI: un lider care transformă ideile tale în carduri și într-un plan, și ajutoare care iau cardurile în ordinea priorității. Când ceva e construit, un tester AI urmează pașii de test și îți arată ce a văzut. Apoi așteaptă într-o singură grămadă numită Pentru tine. O accepți sau lași un comentariu și echipa mai încearcă o dată. Nimic nu ajunge vreodată la Gata fără tine.","Câteva lucruri la care poate nu te aștepți. O veghe de noapte ține coloana De făcut plină cât dormi, alegând carduri care nu cer niciun răspuns de la tine. Un contor de tokeni arată cât au folosit agenții azi și săptămâna asta, iar Modul fără tokeni le spune să nu mai cheltuiască. Poți scrie prietenilor, iar mesajele private sunt criptate de la un capăt la altul. Tabla vorbește vreo 120 de limbi, printre ele neerlandeza, flamanda, limba piraților și klingoniana. Nimic din toate astea nu costă un ban și nimeni nu încearcă să ți le vândă.","AI-gile este un proiect mic, personal, nu o companie. Rich voia să țină sub ochi mai multe proiecte de programare cu AI fără să deschidă fiecare aplicație, așa că el și agenții au făcut o tablă pentru asta, apoi au folosit tabla ca să construiască restul. E în pre-alfa închis, ceea ce înseamnă că merge, mai mult sau mai puțin, pentru o mână de prieteni. Nu există pagină de prețuri, buletin informativ sau plan de creștere. Dacă ți se pare util, poți cere să-l încerci când se deschide puțin mai mult."]},{"n":144,"texts":["AI-gile este o tablă kanban pentru un om și o mulțime de agenți AI. Rulează pe propriul tău calculator și este complet gratuită. Adaugi proiecte, iar fiecare proiect primește un lider și o echipă mică. Vorbești cu liderul, cam ca pe Discord, și îi descrii o idee; el o transformă în carduri și într-un plan, apoi așteaptă să apeși Go. Echipa parcurge cardurile în ordinea priorității, folosind o linie de comandă simplă, făcută pentru modelele de limbaj. Înainte să-ți revină ceva, un tester AI urmează pașii într-o copie a aplicației și atașează o captură de ecran. Munca terminată ajunge în grămada ta, cu fișierele schimbate și diferențele. O accepți sau lași un comentariu, iar echipa se trezește și mai încearcă. Doar tu poți muta un card la Gata.","O zi cu AI-gile, în mare. Seara lași câteva comentarii: butonul ăsta e într-un loc nepotrivit, lista aceea ar trebui sortată, am putea avea o temă întunecată. Te duci la culcare. Agenții citesc comentariile, fac schimbările, le testează și ți le dau înapoi. Dacă De făcut rămâne gol, veghea de noapte îl umple din backlog cu carduri care nu cer niciun răspuns de la tine. Dimineața e o singură grămadă scurtă: două întrebări și câteva lucruri de încercat, fiecare cu pași pe care îi poate urma un om somnoros și cu o captură de ecran în care merge. Dai clic prin ele, accepți ce e bun și trimiți înapoi restul. Un contor de tokeni arată cât s-a folosit, iar Modul fără tokeni e pentru săptămânile slabe. Apoi iei micul dejun, la care agenții încă nu pot ajuta.","Mai întâi, ce nu este AI-gile. Nu e un start-up, nu e de vânzare și nimeni nu-ți adună datele. E o tablă gratuită care rulează pe calculatorul tău, fără conturi, fără urmăritoare și fără cookie-uri. Ce este: un singur loc ordonat unde vezi toate proiectele de programare cu AI deodată, cu o echipă de agenți care fac cardurile și tu care iei deciziile. Unește cardurile înrudite, repară titlurile încurcate și urmărește cât de suplu rămâne codul. Vorbește vreo 120 de limbi, de la neerlandeză și flamandă până la limba piraților și klingoniană. Prietenii își pot scrie unii altora, în privat și criptat. A fost construit de Rich și de o mulțime de agenți răbdători, mai ales folosindu-se pe el însuși. E în pre-alfa închis, deci pe alocuri e aspru. Dacă ți se pare distractiv, cere frumos și poate intri mai devreme."]}],"quips":{"1":"Un cuvânt. Îndrăzneț. Poate prea îndrăzneț.","3":"Trei cuvinte. Deja mai cinstit decât majoritatea paginilor de produs.","8":"Opt cuvinte. Tot mai scurt decât un stand-up.","21":"Apropo, lungimile sunt puncte de poveste. Bineînțeles că sunt.","55":"Cincizeci și cinci de cuvinte. Două carduri s-au terminat cât ai citit.","144":"Asta e cea lungă. Nu există 233. Agenții s-au culcat."}},"timeline":{"first-idea.name":"Prima idee","first-idea.line":"Prima discuție, înainte să existe vreun rând de cod.","first-board.name":"Prima tablă","first-board.line":"O tablă care își urmărește propria construcție: carduri, coloane, tragere și plasare, proiecte.","team-roles.name":"Echipă și roluri","team-roles.line":"Profiluri de agenți, șabloane de echipă, spații și cine ce face.","install.name":"Instalare și versiuni","install.line":"Un zip pe care îl poate instala un prieten, actualizări automate, canale și revenire la versiunea veche.","usage-saver.name":"Economie de consum","usage-saver.line":"Măsori cât costă rulările, ții codul suplu, îți economisești limita.","friends.name":"Prieteni și partajare","friends.line":"Mesaje private, un releu criptat, invitații, roluri și proiecte partajate.","languages.name":"Limbi","languages.line":"Fiecare text din ecrane într-un fișier de limbă, cu neerlandeza și flamanda prima.","ai-tester.name":"Tester AI","ai-tester.line":"Un tester verifică fiecare predare mai întâi și arată ce a văzut.","website.name":"Site-ul","website.line":"aigile.lol, pagina de prezentare și această cronologie.","streaming.name":"Chat și streaming","streaming.line":"Discord, Twitch, OBS, modul de streamer, GIF-uri și emoji.","no-ai.name":"Ediția fără AI","no-ai.line":"O tablă pentru cei care programează fără AI, și table publice.","night-watch.name":"Veghea de noapte","night-watch.line":"Un paznic și un Scrum Master țin echipele la treabă cât dormi.","p-more.name":"Tot restul","p-more.line":"Idei mai mici care își așteaptă rândul.","p-android.name":"Telefon și Android","p-android.line":"Ajungi la tablă de pe telefon, apoi printr-o aplicație Android nativă.","p-release.name":"Alfa și mai departe","p-release.line":"Alfa închis, site-ul live, apoi beta.","p-languages.name":"Mai multe limbi","p-languages.line":"Peste o sută de limbi și un mod de imersiune pentru cei care învață.","p-engines.name":"Mai multe motoare AI","p-engines.line":"Alegi Claude, Codex sau Gemini pentru fiecare agent.","p-pro.name":"Practică profesionistă","p-pro.line":"Etichete de risc, porți de îmbinare, carduri de incident și balustrade de siguranță.","p-self.name":"Grijă de tine","p-self.line":"Mod obosit, mementouri de îngrijire de sine și 4:20.","p-servers.name":"Servere și scară","p-servers.line":"Setări globale de server, roluri și planificare pentru creștere.","p-livestream.name":"Extra pentru streaming","p-livestream.line":"Chat Twitch, emoji proprii și o vedere publică live."},"words":{"button":"📖 Cuvinte de dezvoltator","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Caută un cuvânt…","none":"Niciun cuvânt nu se potrivește.","close":"Închide","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Dosarul proiectului cu cod și întregul istoric de commit-uri, de obicei ținut și pe GitHub.","also":["repository","repo-ul","repo-uri"]},{"id":"branch","g":"build","word":"Branch","text":"O linie de lucru separată în cod, ca să poți face modificări fără să atingi versiunea principală.","also":["branch-uri","branch-ul","branch-urile"]},{"id":"commit","g":"build","word":"Commit","text":"Un instantaneu salvat al codului, cu o scurtă notă despre ce s-a schimbat. Poți reveni oricând la el.","also":["commit-uri","commit-ul","commit-urile"]},{"id":"push","g":"build","word":"Push","text":"Trimiterea instantaneelor salvate (commit-uri) de pe acest calculator pe GitHub, ca să fie păstrate în siguranță și partajate."},{"id":"merge","g":"build","word":"Merge","text":"Reunirea modificărilor unui branch în versiunea principală."},{"id":"pr","g":"build","word":"Pull request","text":"Cerere ca modificările unui branch să fie verificate și unite în versiunea principală.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Curățarea codului fără a-i schimba funcția: fișiere mai mici, nume mai clare, mai puține repetiții."},{"id":"bug","g":"build","word":"Bug","text":"Ceva care nu funcționează așa cum ar trebui.","also":["bug-uri","bug-ul","bug-urile","bug-urilor"]},{"id":"test","g":"build","word":"Test","text":"Încercarea unei bucăți de muncă terminate ca să verifici că face ce s-a cerut, înainte s-o accepți.","also":["teste","testul","testului","testare","testat","testezi","testarea"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Publicarea unei versiuni noi live, de exemplu pe un server unde o folosesc oamenii."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Idei și muncă încă neplanificate. Nimic de acolo nu se lucrează până nu trece în De făcut."},{"id":"sprint","g":"team","word":"Sprint","text":"O perioadă scurtă de muncă (adesea o săptămână sau două) cu un set convenit de carduri de terminat.","also":["sprinturi","sprinturile","sprintul","sprintului","sprinturilor"]},{"id":"standup","g":"team","word":"Stand-up","text":"Un check-in rapid: ce a făcut fiecare membru al echipei, ce face în continuare și ce îl oprește.","also":["standup","stand-up-uri","stand-up-ul","stand-upuri","stand-upurile"]},{"id":"kanban","g":"team","word":"Kanban","text":"Un board cu coloane (De făcut, În lucru, Gata) în care cardurile merg de la stânga la dreapta pe măsură ce se lucrează."},{"id":"wip","g":"team","word":"Limită WIP","text":"Work in progress: cel mult câte carduri să țină o coloană, ca echipa să termine lucrurile înainte să înceapă altele.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Un AI care lucrează singur la o sarcină: citește codul, face modificări, rulează verificări și raportează.","also":["agenți","agentul","agentului"]},{"id":"token","g":"team","word":"Token","text":"Unitatea în care se numără utilizarea AI: aproximativ câteva litere de text citit sau scris. Mai puțini tokeni, mai mult rămas din plan.","also":["tokeni","tokenii","tokenilor"]},{"id":"hook","g":"team","word":"Hook","text":"O mică comandă care rulează singură la un moment stabilit, de ex. când pornește o sesiune AI, ca echipa să audă comentariile tale.","also":["hook-uri","hook-ul","hook-urile"]}]}};
